import{_ as c,V as i,W as l,Z as a,Y as n,a0 as s,X as p,F as e}from"./framework-9f272d12.js";const u={},r=p('<h1 id="面试官-agent-直接调支付接口转钱-有什么问题-——敏感授权怎么答出深度" tabindex="-1"><a class="header-anchor" href="#面试官-agent-直接调支付接口转钱-有什么问题-——敏感授权怎么答出深度" aria-hidden="true">#</a> 面试官：Agent 直接调支付接口转钱，有什么问题？——敏感授权怎么答出深度</h1><figure><img src="https://imgbed.ppai.top/file/1777274061995_m4-cover.jpeg" alt="m4-cover.jpeg" tabindex="0" loading="lazy"><figcaption>m4-cover.jpeg</figcaption></figure><h2 id="_1-引言" tabindex="-1"><a class="header-anchor" href="#_1-引言" aria-hidden="true">#</a> 1. 引言</h2><p>在 Agent 系统开发的面试中，<strong>敏感工具授权</strong>是一个极其重要但又常被忽视的考察点。当面试官问起&quot;如果用户让 Agent 转账 1000 块钱，Agent 直接就调用支付工具把钱转走了，连确认环节都没有，你覺得这个设计有什么问题？&quot;时，敏感工具授权就是必考的内容。</p><p>本文从面试官视角，系统性地解析这道题的考察层次、问题本质、解决方案，以及如何在面试中展现自己的深度。</p><h2 id="_2-面试高频问题" tabindex="-1"><a class="header-anchor" href="#_2-面试高频问题" aria-hidden="true">#</a> 2. 面试高频问题</h2><h3 id="_2-1-典型面试问题" tabindex="-1"><a class="header-anchor" href="#_2-1-典型面试问题" aria-hidden="true">#</a> 2.1 典型面试问题</h3><p>在 Agent 开发岗位的面试中，面试官通常会通过以下方式考察这个问题：</p><figure><img src="https://imgbed.ppai.top/file/1777274066050_m4-07.jpeg" alt="m4-07.jpeg" tabindex="0" loading="lazy"><figcaption>m4-07.jpeg</figcaption></figure><p><strong>初级问题</strong>：</p><ul><li>&quot;如果用户说&#39;帮我转1000块给张三&#39;，Agent 直接就调用支付工具转钱，这个流程有什么问题？&quot;</li><li>&quot;敏感操作需不需要用户确认？怎么加确认环节？&quot;</li><li>&quot;Agent 自动执行和人工确认之间怎么平衡？&quot;</li></ul><p><strong>进阶问题</strong>：</p><ul><li>&quot;敏感工具的安全等级怎么定义？哪些算敏感操作？&quot;</li><li>&quot;授权通过后的上下文怎么和 Agent 的执行上下文同步？&quot;</li><li>&quot;如果用户授权后，参数变了怎么办？&quot;</li><li>&quot;批量敏感操作（比如一次订10张机票）怎么处理？&quot;</li><li>&quot;授权有有效期的概念吗？过期了怎么处理？&quot;</li></ul><p><strong>深度问题</strong>：</p><ul><li>&quot;授权应该发生在哪个环节？是 Agent 决定调用工具之前，还是工具实际执行之前？&quot;</li><li>&quot;如果之前授权，授权通过后 Agent 的上下文已经变了怎么办？&quot;</li><li>&quot;如果之后授权，授权通过后 Agent 可能已经忘记自己要干什么了，怎么办？&quot;</li><li>&quot;如何设计一个可扩展的敏感工具授权框架？&quot;</li><li>&quot;如何平衡自动化和安全性之间的矛盾？&quot;</li></ul><h3 id="_2-2-面试官的考察点" tabindex="-1"><a class="header-anchor" href="#_2-2-面试官的考察点" aria-hidden="true">#</a> 2.2 面试官的考察点</h3><table><thead><tr><th>考察维度</th><th>面试官想看到的</th></tr></thead><tbody><tr><td>安全意识</td><td>能否意识到敏感操作的潜在风险</td></tr><tr><td>方案设计</td><td>能否提出分级的授权方案</td></tr><tr><td>工程实现</td><td>能否给出具体的授权流程设计代码</td></tr><tr><td>权衡思维</td><td>能否认识到自动化和安全性的矛盾</td></tr><tr><td>边界考虑</td><td>能否考虑到授权上下文同步、批量操作等边界情况</td></tr></tbody></table><h2 id="_3-问题本质" tabindex="-1"><a class="header-anchor" href="#_3-问题本质" aria-hidden="true">#</a> 3. 问题本质</h2><h3 id="_3-1-核心矛盾" tabindex="-1"><a class="header-anchor" href="#_3-1-核心矛盾" aria-hidden="true">#</a> 3.1 核心矛盾</h3><figure><img src="https://imgbed.ppai.top/file/1777274063218_m4-01.jpeg" alt="m4-01.jpeg" tabindex="0" loading="lazy"><figcaption>m4-01.jpeg</figcaption></figure>',20),d=p(`<p><strong>核心矛盾</strong>：Agent 的优势是&quot;自动化&quot;，但自动化和&quot;安全&quot;天然矛盾。完全让 Agent 自主执行，涉及资金、隐私数据的操作就有风险。</p><h3 id="_3-2-问题量化分析" tabindex="-1"><a class="header-anchor" href="#_3-2-问题量化分析" aria-hidden="true">#</a> 3.2 问题量化分析</h3><table><thead><tr><th>维度</th><th>挑战描述</th></tr></thead><tbody><tr><td>时机选择</td><td>授权应该在决策前还是执行前？两个时机各有难题</td></tr><tr><td>上下文同步</td><td>授权通过后上下文变了，参数还是原来那个吗？</td></tr><tr><td>安全等级</td><td>敏感工具的&quot;敏感&quot;程度怎么定义？</td></tr><tr><td>批量操作</td><td>10个敏感操作需要10次授权吗？</td></tr><tr><td>有效期</td><td>授权有有效期吗？过期了怎么办？</td></tr></tbody></table><h2 id="_4-方案对比" tabindex="-1"><a class="header-anchor" href="#_4-方案对比" aria-hidden="true">#</a> 4. 方案对比</h2><h3 id="_4-1-方案一-无授权-最初级" tabindex="-1"><a class="header-anchor" href="#_4-1-方案一-无授权-最初级" aria-hidden="true">#</a> 4.1 方案一：无授权（最初级）</h3><p>直接让 Agent 执行敏感操作，没有任何授权环节。</p><div class="language-python line-numbers-mode" data-ext="py"><pre class="language-python"><code><span class="token comment"># 最简方案：直接执行</span>
<span class="token keyword">async</span> <span class="token keyword">def</span> <span class="token function">execute_transfer</span><span class="token punctuation">(</span>amount<span class="token punctuation">:</span> <span class="token builtin">int</span><span class="token punctuation">,</span> to<span class="token punctuation">:</span> <span class="token builtin">str</span><span class="token punctuation">)</span><span class="token punctuation">:</span>
    <span class="token keyword">await</span> payment_api<span class="token punctuation">.</span>transfer<span class="token punctuation">(</span>amount<span class="token punctuation">,</span> to<span class="token punctuation">)</span>
    <span class="token keyword">return</span> <span class="token string">&quot;转账成功&quot;</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p><strong>现状</strong>：很多 Agent 原型就是这样实现的，确实&quot;自动化&quot;，但也确实危险。</p><p><strong>适用场景</strong>：内部 AI 助手、完全可信的环境、测试用途。</p><h3 id="_4-2-方案二-执行前授权-主流方案" tabindex="-1"><a class="header-anchor" href="#_4-2-方案二-执行前授权-主流方案" aria-hidden="true">#</a> 4.2 方案二：执行前授权（主流方案）</h3><p>在工具实际执行之前，需要用户确认。</p><div class="language-python line-numbers-mode" data-ext="py"><pre class="language-python"><code><span class="token keyword">class</span> <span class="token class-name">PreExecutionAuthenticator</span><span class="token punctuation">:</span>
    <span class="token keyword">def</span> <span class="token function">__init__</span><span class="token punctuation">(</span>self<span class="token punctuation">)</span><span class="token punctuation">:</span>
        self<span class="token punctuation">.</span>sensitive_tools <span class="token operator">=</span> <span class="token punctuation">{</span>
            <span class="token string">&quot;transfer&quot;</span><span class="token punctuation">:</span> AuthLevel<span class="token punctuation">.</span>HIGH<span class="token punctuation">,</span>
            <span class="token string">&quot;delete_account&quot;</span><span class="token punctuation">:</span> AuthLevel<span class="token punctuation">.</span>HIGH<span class="token punctuation">,</span>
            <span class="token string">&quot;send_email&quot;</span><span class="token punctuation">:</span> AuthLevel<span class="token punctuation">.</span>MEDIUM<span class="token punctuation">,</span>
            <span class="token string">&quot;book_ticket&quot;</span><span class="token punctuation">:</span> AuthLevel<span class="token punctuation">.</span>LOW<span class="token punctuation">,</span>
        <span class="token punctuation">}</span>
    
    <span class="token keyword">async</span> <span class="token keyword">def</span> <span class="token function">check_auth</span><span class="token punctuation">(</span>self<span class="token punctuation">,</span> tool_name<span class="token punctuation">:</span> <span class="token builtin">str</span><span class="token punctuation">,</span> params<span class="token punctuation">:</span> <span class="token builtin">dict</span><span class="token punctuation">)</span> <span class="token operator">-</span><span class="token operator">&gt;</span> AuthResult<span class="token punctuation">:</span>
        auth_level <span class="token operator">=</span> self<span class="token punctuation">.</span>sensitive_tools<span class="token punctuation">.</span>get<span class="token punctuation">(</span>tool_name<span class="token punctuation">,</span> AuthLevel<span class="token punctuation">.</span>LOW<span class="token punctuation">)</span>
        
        <span class="token keyword">if</span> auth_level <span class="token operator">==</span> AuthLevel<span class="token punctuation">.</span>HIGH<span class="token punctuation">:</span>
            <span class="token comment"># 高敏感：需要显式确认</span>
            confirmed <span class="token operator">=</span> <span class="token keyword">await</span> self<span class="token punctuation">.</span>request_user_confirmation<span class="token punctuation">(</span>tool_name<span class="token punctuation">,</span> params<span class="token punctuation">)</span>
            <span class="token keyword">if</span> <span class="token keyword">not</span> confirmed<span class="token punctuation">:</span>
                <span class="token keyword">return</span> AuthResult<span class="token punctuation">(</span>rejected<span class="token operator">=</span><span class="token boolean">True</span><span class="token punctuation">,</span> reason<span class="token operator">=</span><span class="token string">&quot;用户拒绝&quot;</span><span class="token punctuation">)</span>
        
        <span class="token keyword">return</span> AuthResult<span class="token punctuation">(</span>approved<span class="token operator">=</span><span class="token boolean">True</span><span class="token punctuation">)</span>
    
    <span class="token keyword">async</span> <span class="token keyword">def</span> <span class="token function">execute_with_auth</span><span class="token punctuation">(</span>self<span class="token punctuation">,</span> tool<span class="token punctuation">:</span> Tool<span class="token punctuation">,</span> params<span class="token punctuation">:</span> <span class="token builtin">dict</span><span class="token punctuation">)</span> <span class="token operator">-</span><span class="token operator">&gt;</span> ToolResult<span class="token punctuation">:</span>
        <span class="token comment"># 执行前检查授权</span>
        auth_result <span class="token operator">=</span> <span class="token keyword">await</span> self<span class="token punctuation">.</span>check_auth<span class="token punctuation">(</span>tool<span class="token punctuation">.</span>name<span class="token punctuation">,</span> params<span class="token punctuation">)</span>
        
        <span class="token keyword">if</span> auth_result<span class="token punctuation">.</span>rejected<span class="token punctuation">:</span>
            <span class="token keyword">return</span> ToolResult<span class="token punctuation">(</span>success<span class="token operator">=</span><span class="token boolean">False</span><span class="token punctuation">,</span> error<span class="token operator">=</span>auth_result<span class="token punctuation">.</span>reason<span class="token punctuation">)</span>
        
        <span class="token comment"># 授权通过，执行工具</span>
        <span class="token keyword">return</span> <span class="token keyword">await</span> tool<span class="token punctuation">.</span>execute<span class="token punctuation">(</span>params<span class="token punctuation">)</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p><strong>流程</strong>：</p><ol><li>Agent 决定调用支付工具</li><li>系统拦截，弹窗让用户确认</li><li>用户确认后，执行转账</li><li>返回结果</li></ol><h4 id="补充说明" tabindex="-1"><a class="header-anchor" href="#补充说明" aria-hidden="true">#</a> 补充说明</h4><p><strong>问题一</strong>：授权时用的参数，和执行时的参数可能不一样了。</p><p><strong>解决</strong>：授权时锁定参数，执行时校验。</p><div class="language-python line-numbers-mode" data-ext="py"><pre class="language-python"><code><span class="token keyword">class</span> <span class="token class-name">ParameterLockingAuthenticator</span><span class="token punctuation">:</span>
    <span class="token keyword">def</span> <span class="token function">__init__</span><span class="token punctuation">(</span>self<span class="token punctuation">)</span><span class="token punctuation">:</span>
        self<span class="token punctuation">.</span>pending_auths <span class="token operator">=</span> <span class="token punctuation">{</span><span class="token punctuation">}</span>
    
    <span class="token keyword">async</span> <span class="token keyword">def</span> <span class="token function">request_confirmation</span><span class="token punctuation">(</span>self<span class="token punctuation">,</span> tool_name<span class="token punctuation">:</span> <span class="token builtin">str</span><span class="token punctuation">,</span> params<span class="token punctuation">:</span> <span class="token builtin">dict</span><span class="token punctuation">)</span> <span class="token operator">-</span><span class="token operator">&gt;</span> <span class="token builtin">str</span><span class="token punctuation">:</span>
        <span class="token comment"># 生成授权令牌</span>
        auth_token <span class="token operator">=</span> generate_token<span class="token punctuation">(</span><span class="token punctuation">)</span>
        
        <span class="token comment"># 锁定当前参数</span>
        self<span class="token punctuation">.</span>pending_auths<span class="token punctuation">[</span>auth_token<span class="token punctuation">]</span> <span class="token operator">=</span> <span class="token punctuation">{</span>
            <span class="token string">&quot;tool_name&quot;</span><span class="token punctuation">:</span> tool_name<span class="token punctuation">,</span>
            <span class="token string">&quot;params&quot;</span><span class="token punctuation">:</span> params<span class="token punctuation">,</span>
            <span class="token string">&quot;locked_at&quot;</span><span class="token punctuation">:</span> datetime<span class="token punctuation">.</span>now<span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">,</span>
            <span class="token string">&quot;expires_in&quot;</span><span class="token punctuation">:</span> <span class="token number">300</span><span class="token punctuation">,</span>  <span class="token comment"># 5分钟有效期</span>
        <span class="token punctuation">}</span>
        
        <span class="token comment"># 返回给用户确认</span>
        <span class="token keyword">return</span> auth_token
    
    <span class="token keyword">async</span> <span class="token keyword">def</span> <span class="token function">execute_with_auth</span><span class="token punctuation">(</span>self<span class="token punctuation">,</span> auth_token<span class="token punctuation">:</span> <span class="token builtin">str</span><span class="token punctuation">)</span> <span class="token operator">-</span><span class="token operator">&gt;</span> ToolResult<span class="token punctuation">:</span>
        auth <span class="token operator">=</span> self<span class="token punctuation">.</span>pending_auths<span class="token punctuation">.</span>get<span class="token punctuation">(</span>auth_token<span class="token punctuation">)</span>
        
        <span class="token keyword">if</span> <span class="token keyword">not</span> auth<span class="token punctuation">:</span>
            <span class="token keyword">return</span> ToolResult<span class="token punctuation">(</span>success<span class="token operator">=</span><span class="token boolean">False</span><span class="token punctuation">,</span> error<span class="token operator">=</span><span class="token string">&quot;授权已失效&quot;</span><span class="token punctuation">)</span>
        
        <span class="token keyword">if</span> datetime<span class="token punctuation">.</span>now<span class="token punctuation">(</span><span class="token punctuation">)</span> <span class="token operator">-</span> auth<span class="token punctuation">[</span><span class="token string">&quot;locked_at&quot;</span><span class="token punctuation">]</span> <span class="token operator">&gt;</span> timedelta<span class="token punctuation">(</span>seconds<span class="token operator">=</span>auth<span class="token punctuation">[</span><span class="token string">&quot;expires_in&quot;</span><span class="token punctuation">]</span><span class="token punctuation">)</span><span class="token punctuation">:</span>
            <span class="token keyword">return</span> ToolResult<span class="token punctuation">(</span>success<span class="token operator">=</span><span class="token boolean">False</span><span class="token punctuation">,</span> error<span class="token operator">=</span><span class="token string">&quot;授权已过期&quot;</span><span class="token punctuation">)</span>
        
        <span class="token comment"># 使用锁定时的参数执行</span>
        tool <span class="token operator">=</span> self<span class="token punctuation">.</span>get_tool<span class="token punctuation">(</span>auth<span class="token punctuation">[</span><span class="token string">&quot;tool_name&quot;</span><span class="token punctuation">]</span><span class="token punctuation">)</span>
        <span class="token keyword">return</span> <span class="token keyword">await</span> tool<span class="token punctuation">.</span>execute<span class="token punctuation">(</span>auth<span class="token punctuation">[</span><span class="token string">&quot;params&quot;</span><span class="token punctuation">]</span><span class="token punctuation">)</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p><strong>问题二</strong>：上面的实现中，对于授权时锁定参数，但遗漏了关键的防重设计，如果auth_token被重复使用了怎么办？</p><p>当前 token：</p><p>可以被重复使用 没有标记“已消费”</p><p><strong>解决</strong>：在auth中维护使用状态</p><div class="language-python line-numbers-mode" data-ext="py"><pre class="language-python"><code><span class="token keyword">if</span> auth<span class="token punctuation">[</span><span class="token string">&quot;used&quot;</span><span class="token punctuation">]</span><span class="token punctuation">:</span>
    reject<span class="token punctuation">(</span><span class="token punctuation">)</span>

auth<span class="token punctuation">[</span><span class="token string">&quot;used&quot;</span><span class="token punctuation">]</span> <span class="token operator">=</span> <span class="token boolean">True</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p><strong>问题三</strong>：没有绑定用户身份，任何人拿到token都能执行</p><p><strong>解决</strong>： 在实际的生产环境中，需要绑定用户身份</p><div class="language-python line-numbers-mode" data-ext="py"><pre class="language-python"><code><span class="token string">&quot;user_id&quot;</span> <span class="token operator">=</span> xxx
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div></div></div><h4 id="小结" tabindex="-1"><a class="header-anchor" href="#小结" aria-hidden="true">#</a> 小结</h4><p>这种方案可以说是比较常见也比较容易想到的实现了，当然在实际项目中要用好时，还需要搭配会话状态来使用，避免出现这一轮问答要求用户进行授权，但是用户完全不按照你的操作，开始了其他的新话题</p><p><strong>适用场景</strong>：大多数生产环境，<strong>推荐使用</strong></p><p>虽然本文将这个方案标记为主流方案，但是你需要清楚一点，现实世界并不是单一方案，通常是一事一议，一个严谨的生产系统中，更推荐的是</p><ul><li>预授权（策略层）</li><li>执行前授权（交互层）</li><li>工具侧校验（强制层）</li></ul><table><thead><tr><th>层级</th><th>作用</th></tr></thead><tbody><tr><td>Agent 层</td><td>决策控制</td></tr><tr><td>授权层</td><td>用户确认</td></tr><tr><td>Tool 层</td><td>最终兜底（必须有）</td></tr></tbody></table><h3 id="_4-3-方案三-决策前授权-保守方案" tabindex="-1"><a class="header-anchor" href="#_4-3-方案三-决策前授权-保守方案" aria-hidden="true">#</a> 4.3 方案三：决策前授权（保守方案）</h3><p>在 Agent 决定调用敏感工具之前就获取授权。</p><div class="language-python line-numbers-mode" data-ext="py"><pre class="language-python"><code><span class="token keyword">class</span> <span class="token class-name">PreDecisionAuthenticator</span><span class="token punctuation">:</span>
    <span class="token keyword">def</span> <span class="token function">__init__</span><span class="token punctuation">(</span>self<span class="token punctuation">)</span><span class="token punctuation">:</span>
        self<span class="token punctuation">.</span>user_preferences <span class="token operator">=</span> <span class="token punctuation">{</span><span class="token punctuation">}</span>
    
    <span class="token keyword">async</span> <span class="token keyword">def</span> <span class="token function">check_pre_auth</span><span class="token punctuation">(</span>self<span class="token punctuation">,</span> user_id<span class="token punctuation">:</span> <span class="token builtin">str</span><span class="token punctuation">,</span> tool_category<span class="token punctuation">:</span> <span class="token builtin">str</span><span class="token punctuation">)</span> <span class="token operator">-</span><span class="token operator">&gt;</span> <span class="token builtin">bool</span><span class="token punctuation">:</span>
        <span class="token comment"># 检查用户是否预授权了这类操作</span>
        pref <span class="token operator">=</span> self<span class="token punctuation">.</span>user_preferences<span class="token punctuation">.</span>get<span class="token punctuation">(</span>user_id<span class="token punctuation">,</span> <span class="token punctuation">{</span><span class="token punctuation">}</span><span class="token punctuation">)</span>
        <span class="token keyword">return</span> pref<span class="token punctuation">.</span>get<span class="token punctuation">(</span><span class="token string-interpolation"><span class="token string">f&quot;allow_</span><span class="token interpolation"><span class="token punctuation">{</span>tool_category<span class="token punctuation">}</span></span><span class="token string">&quot;</span></span><span class="token punctuation">,</span> <span class="token boolean">False</span><span class="token punctuation">)</span>
    
    <span class="token keyword">async</span> <span class="token keyword">def</span> <span class="token function">execute_with_pre_auth</span><span class="token punctuation">(</span>self<span class="token punctuation">,</span> agent<span class="token punctuation">:</span> Agent<span class="token punctuation">,</span> user_request<span class="token punctuation">:</span> <span class="token builtin">str</span><span class="token punctuation">)</span> <span class="token operator">-</span><span class="token operator">&gt;</span> AgentResult<span class="token punctuation">:</span>
        <span class="token comment"># 分析用户请求的意图</span>
        intent <span class="token operator">=</span> <span class="token keyword">await</span> agent<span class="token punctuation">.</span>analyze_intent<span class="token punctuation">(</span>user_request<span class="token punctuation">)</span>
        
        <span class="token comment"># 检查是否需要预授权</span>
        <span class="token keyword">if</span> intent<span class="token punctuation">.</span>requires_pre_auth<span class="token punctuation">:</span>
            has_pre_auth <span class="token operator">=</span> <span class="token keyword">await</span> self<span class="token punctuation">.</span>check_pre_auth<span class="token punctuation">(</span>intent<span class="token punctuation">.</span>user_id<span class="token punctuation">,</span> intent<span class="token punctuation">.</span>tool_category<span class="token punctuation">)</span>
            
            <span class="token keyword">if</span> <span class="token keyword">not</span> has_pre_auth<span class="token punctuation">:</span>
                <span class="token comment"># 需要引导用户先授权</span>
                <span class="token keyword">await</span> self<span class="token punctuation">.</span>request_pre_auth<span class="token punctuation">(</span>intent<span class="token punctuation">.</span>user_id<span class="token punctuation">,</span> intent<span class="token punctuation">.</span>tool_category<span class="token punctuation">)</span>
                <span class="token keyword">return</span> AgentResult<span class="token punctuation">(</span>needs_auth<span class="token operator">=</span><span class="token boolean">True</span><span class="token punctuation">)</span>
        
        <span class="token comment"># 执行 Agent</span>
        <span class="token keyword">return</span> <span class="token keyword">await</span> agent<span class="token punctuation">.</span>execute<span class="token punctuation">(</span>user_request<span class="token punctuation">)</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p><strong>适用场景</strong>：高安全要求环境、企业级应用。</p><h3 id="_4-4-方案四-分级授权体系" tabindex="-1"><a class="header-anchor" href="#_4-4-方案四-分级授权体系" aria-hidden="true">#</a> 4.4 方案四：分级授权体系</h3><figure><img src="https://imgbed.ppai.top/file/1777274063615_m4-02.jpeg" alt="m4-02.jpeg" tabindex="0" loading="lazy"><figcaption>m4-02.jpeg</figcaption></figure><p>根据敏感级别设计不同的授权策略。</p><div class="language-python line-numbers-mode" data-ext="py"><pre class="language-python"><code><span class="token keyword">from</span> enum <span class="token keyword">import</span> IntEnum

<span class="token keyword">class</span> <span class="token class-name">AuthLevel</span><span class="token punctuation">(</span>IntEnum<span class="token punctuation">)</span><span class="token punctuation">:</span>
    NONE <span class="token operator">=</span> <span class="token number">0</span>      <span class="token comment"># 无需授权</span>
    Low <span class="token operator">=</span> <span class="token number">1</span>         <span class="token comment"># 静默授权（如记录日志）</span>
    MEDIUM <span class="token operator">=</span> <span class="token number">2</span>     <span class="token comment"># 简单确认（如点个按钮）</span>
    HIGH <span class="token operator">=</span> <span class="token number">3</span>        <span class="token comment"># 显式确认（如输入密码）</span>
    CRITICAL <span class="token operator">=</span> <span class="token number">4</span>    <span class="token comment"># 多重验证（如密码 + 人脸）</span>

<span class="token keyword">class</span> <span class="token class-name">SensitiveToolConfig</span><span class="token punctuation">:</span>
    <span class="token decorator annotation punctuation">@staticmethod</span>
    <span class="token keyword">def</span> <span class="token function">get_tool_config</span><span class="token punctuation">(</span><span class="token punctuation">)</span> <span class="token operator">-</span><span class="token operator">&gt;</span> <span class="token builtin">dict</span><span class="token punctuation">:</span>
        <span class="token keyword">return</span> <span class="token punctuation">{</span>
            <span class="token comment"># 资金相关：高敏感</span>
            <span class="token string">&quot;transfer&quot;</span><span class="token punctuation">:</span> AuthLevel<span class="token punctuation">.</span>HIGH<span class="token punctuation">,</span>
            <span class="token string">&quot;refund&quot;</span><span class="token punctuation">:</span> AuthLevel<span class="token punctuation">.</span>HIGH<span class="token punctuation">,</span>
            <span class="token string">&quot;purchase&quot;</span><span class="token punctuation">:</span> AuthLevel<span class="token punctuation">.</span>HIGH<span class="token punctuation">,</span>
            
            <span class="token comment"># 数据相关：中敏感</span>
            <span class="token string">&quot;delete_data&quot;</span><span class="token punctuation">:</span> AuthLevel<span class="token punctuation">.</span>MEDIUM<span class="token punctuation">,</span>
            <span class="token string">&quot;export_data&quot;</span><span class="token punctuation">:</span> AuthLevel<span class="token punctuation">.</span>MEDIUM<span class="token punctuation">,</span>
            <span class="token string">&quot;send_email&quot;</span><span class="token punctuation">:</span> AuthLevel<span class="token punctuation">.</span>MEDIUM<span class="token punctuation">,</span>
            
            <span class="token comment"># 权限相关：最高敏感</span>
            <span class="token string">&quot;delete_account&quot;</span><span class="token punctuation">:</span> AuthLevel<span class="token punctuation">.</span>CRITICAL<span class="token punctuation">,</span>
            <span class="token string">&quot;change_password&quot;</span><span class="token punctuation">:</span> AuthLevel<span class="token punctuation">.</span>CRITICAL<span class="token punctuation">,</span>
            <span class="token string">&quot;grant_permission&quot;</span><span class="token punctuation">:</span> AuthLevel<span class="token punctuation">.</span>CRITICAL<span class="token punctuation">,</span>
            
            <span class="token comment"># 查询类：无需授权</span>
            <span class="token string">&quot;query_balance&quot;</span><span class="token punctuation">:</span> AuthLevel<span class="token punctuation">.</span>NONE<span class="token punctuation">,</span>
            <span class="token string">&quot;search&quot;</span><span class="token punctuation">:</span> AuthLevel<span class="token punctuation">.</span>NONE<span class="token punctuation">,</span>
            <span class="token string">&quot;get_profile&quot;</span><span class="token punctuation">:</span> AuthLevel<span class="token punctuation">.</span>NONE<span class="token punctuation">,</span>
        <span class="token punctuation">}</span>

<span class="token keyword">class</span>分级授权器<span class="token punctuation">:</span>
    <span class="token keyword">async</span> <span class="token keyword">def</span> <span class="token function">request_auth</span><span class="token punctuation">(</span>self<span class="token punctuation">,</span> tool_name<span class="token punctuation">:</span> <span class="token builtin">str</span><span class="token punctuation">,</span> params<span class="token punctuation">:</span> <span class="token builtin">dict</span><span class="token punctuation">)</span> <span class="token operator">-</span><span class="token operator">&gt;</span> AuthResult<span class="token punctuation">:</span>
        level <span class="token operator">=</span> SensitiveToolConfig<span class="token punctuation">.</span>get_tool_config<span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">.</span>get<span class="token punctuation">(</span>tool_name<span class="token punctuation">,</span> AuthLevel<span class="token punctuation">.</span>LOW<span class="token punctuation">)</span>
        
        <span class="token keyword">match</span> level<span class="token punctuation">:</span>
            <span class="token keyword">case</span> AuthLevel<span class="token punctuation">.</span>NONE<span class="token punctuation">:</span>
                <span class="token keyword">return</span> AuthResult<span class="token punctuation">(</span>approved<span class="token operator">=</span><span class="token boolean">True</span><span class="token punctuation">)</span>
            
            <span class="token keyword">case</span> AuthLevel<span class="token punctuation">.</span>LOW<span class="token punctuation">:</span>
                <span class="token comment"># 静默授权，记录日志即可</span>
                <span class="token keyword">await</span> self<span class="token punctuation">.</span>log_action<span class="token punctuation">(</span>tool_name<span class="token punctuation">,</span> params<span class="token punctuation">)</span>
                <span class="token keyword">return</span> AuthResult<span class="token punctuation">(</span>approved<span class="token operator">=</span><span class="token boolean">True</span><span class="token punctuation">)</span>
            
            <span class="token keyword">case</span> AuthLevel<span class="token punctuation">.</span>MEDIUM<span class="token punctuation">:</span>
                <span class="token comment"># 简单确认</span>
                <span class="token keyword">return</span> <span class="token keyword">await</span> self<span class="token punctuation">.</span>request_simple_confirmation<span class="token punctuation">(</span>tool_name<span class="token punctuation">,</span> params<span class="token punctuation">)</span>
            
            <span class="token keyword">case</span> AuthLevel<span class="token punctuation">.</span>HIGH<span class="token punctuation">:</span>
                <span class="token comment"># 显式确认</span>
                <span class="token keyword">return</span> <span class="token keyword">await</span> self<span class="token punctuation">.</span>request_explicit_confirmation<span class="token punctuation">(</span>tool_name<span class="token punctuation">,</span> params<span class="token punctuation">)</span>
            
            <span class="token keyword">case</span> AuthLevel<span class="token punctuation">.</span>CRITICAL<span class="token punctuation">:</span>
                <span class="token comment"># 多重验证</span>
                <span class="token keyword">return</span> <span class="token keyword">await</span> self<span class="token punctuation">.</span>request_multi_factor_confirmation<span class="token punctuation">(</span>tool_name<span class="token punctuation">,</span> params<span class="token punctuation">)</span>
            
            <span class="token keyword">case</span> <span class="token keyword">_</span><span class="token punctuation">:</span>
                <span class="token keyword">return</span> AuthResult<span class="token punctuation">(</span>rejected<span class="token operator">=</span><span class="token boolean">True</span><span class="token punctuation">,</span> reason<span class="token operator">=</span><span class="token string">&quot;未知敏感级别&quot;</span><span class="token punctuation">)</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p><strong>分级标准设计</strong>：</p><table><thead><tr><th>级别</th><th>敏感操作示例</th><th>授权方式</th><th>用户感知</th></tr></thead><tbody><tr><td>L0 无需授权</td><td>查询余额、搜索</td><td>直接执行</td><td>无感知</td></tr><tr><td>L1 静默授权</td><td>查看记录</td><td>记录日志即可</td><td>无感知</td></tr><tr><td>L2 简单确认</td><td>删除数据、发送邮件</td><td>点击确认</td><td>1次点击</td></tr><tr><td>L3 显式确认</td><td>转账、付款</td><td>输入密码</td><td>1次输入</td></tr><tr><td>L4 多重验证</td><td>删除账号、授权</td><td>密码+人脸</td><td>2次验证</td></tr></tbody></table><p><strong>适用场景</strong>：大型复杂系统、需要精细化安全控制的企业。<strong>推荐用于生产环境</strong>。</p><h3 id="_4-5-方案对比总结" tabindex="-1"><a class="header-anchor" href="#_4-5-方案对比总结" aria-hidden="true">#</a> 4.5 方案对比总结</h3><figure><img src="https://imgbed.ppai.top/file/1777274068666_m4-04.jpeg" alt="m4-04.jpeg" tabindex="0" loading="lazy"><figcaption>m4-04.jpeg</figcaption></figure><table><thead><tr><th>维度</th><th>无授权</th><th>执行前授权</th><th>决策前授权</th><th>分级授权</th></tr></thead><tbody><tr><td>安全性</td><td>低</td><td>中</td><td>高</td><td>高</td></tr><tr><td>用户体验</td><td>最好</td><td>一般</td><td>较差</td><td>可配置</td></tr><tr><td>实现复杂度</td><td>无</td><td>低</td><td>中</td><td>高</td></tr><tr><td>灵活性</td><td>高</td><td>中</td><td>低</td><td>中</td></tr><tr><td>适用场景</td><td>测试</td><td>普通生产</td><td>高安全</td><td>企业级</td></tr></tbody></table><p><strong>面试话术</strong>：</p><blockquote><p>&quot;敏感工具授权有四种方案：无授权适合测试环境；执行前授权是主流方案，能在关键操作前拦截；决策前授权适合高安全要求；分级授权是工程落地的最优方案，根据敏感层级自动选择授权方式。&quot;</p></blockquote><p><strong>扩展</strong>：</p><p>上面提到的工具授权，默认工具都是信赖执行者；为了体现我们的考虑问题的完备性（Agent -&gt; Pre Auth -&gt; Tool -&gt; Execute），你也在Tool的执行层进行扩展，如</p><ul><li>Tool 默认不信任Agent</li><li>Tool 内部执行时，需要进行安全校验： <ul><li>用户身份</li><li>权限</li><li>风控规则</li></ul></li><li>Tool 内部执行前，需要做好幂等控制（防止重复操作，多次转账）</li></ul><h2 id="_5-深入问题解析" tabindex="-1"><a class="header-anchor" href="#_5-深入问题解析" aria-hidden="true">#</a> 5. 深入问题解析</h2><h3 id="_5-1-授权时机问题-之前还是之后" tabindex="-1"><a class="header-anchor" href="#_5-1-授权时机问题-之前还是之后" aria-hidden="true">#</a> 5.1 授权时机问题：之前还是之后？</h3><figure><img src="https://imgbed.ppai.top/file/1777274066951_m4-03.jpeg" alt="m4-03.jpeg" tabindex="0" loading="lazy"><figcaption>m4-03.jpeg</figcaption></figure><p><strong>核心问题</strong>：授权应该发生在哪个环节？</p><table><thead><tr><th>时机</th><th>优点</th><th>缺点</th></tr></thead><tbody><tr><td>Agent 决策前</td><td>可以在最早期拦截</td><td>上下文可能还不确定</td></tr><tr><td>Agent 决策后、执行前</td><td>参数已确定</td><td>授权通过后上下文可能变了</td></tr><tr><td>工具执行中</td><td>可以实时拦截</td><td>侵入性强，可能中断</td></tr></tbody></table><p><strong>推荐答案</strong>：执行前授权 + 参数锁定。</p><div class="language-python line-numbers-mode" data-ext="py"><pre class="language-python"><code><span class="token keyword">class</span> <span class="token class-name">HybridAuthenticator</span><span class="token punctuation">:</span>
    <span class="token keyword">async</span> <span class="token keyword">def</span> <span class="token function">authenticate_and_execute</span><span class="token punctuation">(</span>
        self<span class="token punctuation">,</span> 
        tool<span class="token punctuation">:</span> Tool<span class="token punctuation">,</span> 
        params<span class="token punctuation">:</span> <span class="token builtin">dict</span><span class="token punctuation">,</span>
        context<span class="token punctuation">:</span> AgentContext
    <span class="token punctuation">)</span> <span class="token operator">-</span><span class="token operator">&gt;</span> ToolResult<span class="token punctuation">:</span>
        <span class="token comment"># 1. Agent 决策后，锁定当前参数</span>
        locked_params <span class="token operator">=</span> self<span class="token punctuation">.</span>lock_params<span class="token punctuation">(</span>params<span class="token punctuation">)</span>
        
        <span class="token comment"># 2. 执行前请求授权（使用锁定参数）</span>
        auth_result <span class="token operator">=</span> <span class="token keyword">await</span> self<span class="token punctuation">.</span>request_auth<span class="token punctuation">(</span>tool<span class="token punctuation">.</span>name<span class="token punctuation">,</span> locked_params<span class="token punctuation">)</span>
        
        <span class="token keyword">if</span> <span class="token keyword">not</span> auth_result<span class="token punctuation">.</span>approved<span class="token punctuation">:</span>
            <span class="token keyword">return</span> ToolResult<span class="token punctuation">(</span>success<span class="token operator">=</span><span class="token boolean">False</span><span class="token punctuation">,</span> error<span class="token operator">=</span><span class="token string">&quot;授权被拒绝&quot;</span><span class="token punctuation">)</span>
        
        <span class="token comment"># 3. 执行时校验参数未被篡改</span>
        <span class="token keyword">if</span> <span class="token keyword">not</span> self<span class="token punctuation">.</span>verify_params<span class="token punctuation">(</span>params<span class="token punctuation">,</span> locked_params<span class="token punctuation">)</span><span class="token punctuation">:</span>
            <span class="token keyword">return</span> ToolResult<span class="token punctuation">(</span>success<span class="token operator">=</span><span class="token boolean">False</span><span class="token punctuation">,</span> error<span class="token operator">=</span><span class="token string">&quot;参数已被篡改&quot;</span><span class="token punctuation">)</span>
        
        <span class="token comment"># 4. 执行工具</span>
        <span class="token keyword">return</span> <span class="token keyword">await</span> tool<span class="token punctuation">.</span>execute<span class="token punctuation">(</span>locked_params<span class="token punctuation">)</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h3 id="_5-2-上下文同步问题" tabindex="-1"><a class="header-anchor" href="#_5-2-上下文同步问题" aria-hidden="true">#</a> 5.2 上下文同步问题</h3><p><strong>核心问题</strong>：授权通过后，Agent 的上下文已经变了，参数还是原来那个吗？</p><div class="language-python line-numbers-mode" data-ext="py"><pre class="language-python"><code><span class="token keyword">class</span> <span class="token class-name">ContextSyncManager</span><span class="token punctuation">:</span>
    <span class="token keyword">def</span> <span class="token function">__init__</span><span class="token punctuation">(</span>self<span class="token punctuation">)</span><span class="token punctuation">:</span>
        self<span class="token punctuation">.</span>auth_contexts <span class="token operator">=</span> <span class="token punctuation">{</span><span class="token punctuation">}</span>
    
    <span class="token keyword">async</span> <span class="token keyword">def</span> <span class="token function">create_auth_context</span><span class="token punctuation">(</span>
        self<span class="token punctuation">,</span> 
        tool_name<span class="token punctuation">:</span> <span class="token builtin">str</span><span class="token punctuation">,</span> 
        params<span class="token punctuation">:</span> <span class="token builtin">dict</span><span class="token punctuation">,</span> 
        agent_context<span class="token punctuation">:</span> AgentContext
    <span class="token punctuation">)</span> <span class="token operator">-</span><span class="token operator">&gt;</span> <span class="token builtin">str</span><span class="token punctuation">:</span>
        <span class="token comment"># 捕获授权时的完整上下文</span>
        auth_token <span class="token operator">=</span> generate_token<span class="token punctuation">(</span><span class="token punctuation">)</span>
        
        self<span class="token punctuation">.</span>auth_contexts<span class="token punctuation">[</span>auth_token<span class="token punctuation">]</span> <span class="token operator">=</span> <span class="token punctuation">{</span>
            <span class="token string">&quot;tool_name&quot;</span><span class="token punctuation">:</span> tool_name<span class="token punctuation">,</span>
            <span class="token string">&quot;params_hash&quot;</span><span class="token punctuation">:</span> hash_params<span class="token punctuation">(</span>params<span class="token punctuation">)</span><span class="token punctuation">,</span>
            <span class="token string">&quot;agent_snapshot&quot;</span><span class="token punctuation">:</span> <span class="token punctuation">{</span>
                <span class="token string">&quot;conversation&quot;</span><span class="token punctuation">:</span> agent_context<span class="token punctuation">.</span>conversation<span class="token punctuation">[</span><span class="token punctuation">:</span><span class="token number">5</span><span class="token punctuation">]</span><span class="token punctuation">,</span>
                <span class="token string">&quot;user_intent&quot;</span><span class="token punctuation">:</span> agent_context<span class="token punctuation">.</span>inferred_intent<span class="token punctuation">,</span>
                <span class="token string">&quot;plan&quot;</span><span class="token punctuation">:</span> agent_context<span class="token punctuation">.</span>current_plan<span class="token punctuation">,</span>
            <span class="token punctuation">}</span><span class="token punctuation">,</span>
            <span class="token string">&quot;created_at&quot;</span><span class="token punctuation">:</span> datetime<span class="token punctuation">.</span>now<span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">,</span>
        <span class="token punctuation">}</span>
        
        <span class="token keyword">return</span> auth_token
    
    <span class="token keyword">async</span> <span class="token keyword">def</span> <span class="token function">verify_context</span><span class="token punctuation">(</span>
        self<span class="token punctuation">,</span> 
        auth_token<span class="token punctuation">:</span> <span class="token builtin">str</span><span class="token punctuation">,</span> 
        current_context<span class="token punctuation">:</span> AgentContext
    <span class="token punctuation">)</span> <span class="token operator">-</span><span class="token operator">&gt;</span> ContextVerification<span class="token punctuation">:</span>
        auth <span class="token operator">=</span> self<span class="token punctuation">.</span>auth_contexts<span class="token punctuation">.</span>get<span class="token punctuation">(</span>auth_token<span class="token punctuation">)</span>
        
        <span class="token comment"># 检查意图是否一致</span>
        intent_changed <span class="token operator">=</span> <span class="token punctuation">(</span>
            auth<span class="token punctuation">[</span><span class="token string">&quot;agent_snapshot&quot;</span><span class="token punctuation">]</span><span class="token punctuation">[</span><span class="token string">&quot;user_intent&quot;</span><span class="token punctuation">]</span> 
            <span class="token operator">!=</span> current_context<span class="token punctuation">.</span>inferred_intent
        <span class="token punctuation">)</span>
        
        <span class="token comment"># 检查计划是否一致</span>
        plan_changed <span class="token operator">=</span> <span class="token punctuation">(</span>
            auth<span class="token punctuation">[</span><span class="token string">&quot;agent_snapshot&quot;</span><span class="token punctuation">]</span><span class="token punctuation">[</span><span class="token string">&quot;plan&quot;</span><span class="token punctuation">]</span> 
            <span class="token operator">!=</span> current_context<span class="token punctuation">.</span>current_plan
        <span class="token punctuation">)</span>
        
        <span class="token keyword">return</span> ContextVerification<span class="token punctuation">(</span>
            consistent<span class="token operator">=</span><span class="token keyword">not</span> intent_changed <span class="token keyword">and</span> <span class="token keyword">not</span> plan_changed<span class="token punctuation">,</span>
            intent_changed<span class="token operator">=</span>intent_changed<span class="token punctuation">,</span>
            plan_changed<span class="token operator">=</span>plan_changed<span class="token punctuation">,</span>
        <span class="token punctuation">)</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p><strong>处理策略</strong>：</p><figure><img src="https://imgbed.ppai.top/file/1777274078403_m4-05.jpeg" alt="m4-05.jpeg" tabindex="0" loading="lazy"><figcaption>m4-05.jpeg</figcaption></figure><table><thead><tr><th>变化情况</th><th>处理方式</th></tr></thead><tbody><tr><td>参数变了</td><td>重新授权</td></tr><tr><td>意图变了</td><td>拒绝执行，重新开始</td></tr><tr><td>计划变了</td><td>提示用户，重新授权</td></tr></tbody></table><h3 id="_5-3-批量敏感操作处理" tabindex="-1"><a class="header-anchor" href="#_5-3-批量敏感操作处理" aria-hidden="true">#</a> 5.3 批量敏感操作处理</h3><p><strong>核心问题</strong>：如果一次订 10 张机票，需要 10 次授权吗？</p><figure><img src="https://imgbed.ppai.top/file/1777274085601_m4-06.jpeg" alt="m4-06.jpeg" tabindex="0" loading="lazy"><figcaption>m4-06.jpeg</figcaption></figure><div class="language-python line-numbers-mode" data-ext="py"><pre class="language-python"><code><span class="token keyword">class</span> <span class="token class-name">BatchAuthHandler</span><span class="token punctuation">:</span>
    <span class="token keyword">async</span> <span class="token keyword">def</span> <span class="token function">handle_batch_operation</span><span class="token punctuation">(</span>
        self<span class="token punctuation">,</span> 
        tool<span class="token punctuation">:</span> Tool<span class="token punctuation">,</span> 
        batch_params<span class="token punctuation">:</span> <span class="token builtin">list</span><span class="token punctuation">[</span><span class="token builtin">dict</span><span class="token punctuation">]</span>
    <span class="token punctuation">)</span> <span class="token operator">-</span><span class="token operator">&gt;</span> ToolResult<span class="token punctuation">:</span>
        <span class="token comment"># 1. 判断是否为批量操作</span>
        <span class="token keyword">if</span> <span class="token builtin">len</span><span class="token punctuation">(</span>batch_params<span class="token punctuation">)</span> <span class="token operator">&gt;</span> <span class="token number">1</span><span class="token punctuation">:</span>
            <span class="token comment"># 2. 批量操作统一授权</span>
            confirmed <span class="token operator">=</span> <span class="token keyword">await</span> self<span class="token punctuation">.</span>request_batch_confirmation<span class="token punctuation">(</span>
                tool<span class="token punctuation">.</span>name<span class="token punctuation">,</span>
                <span class="token builtin">len</span><span class="token punctuation">(</span>batch_params<span class="token punctuation">)</span><span class="token punctuation">,</span>
                batch_params<span class="token punctuation">[</span><span class="token number">0</span><span class="token punctuation">]</span>  <span class="token comment"># 显示第一个作为示例</span>
            <span class="token punctuation">)</span>
            
            <span class="token keyword">if</span> <span class="token keyword">not</span> confirmed<span class="token punctuation">:</span>
                <span class="token keyword">return</span> ToolResult<span class="token punctuation">(</span>success<span class="token operator">=</span><span class="token boolean">False</span><span class="token punctuation">,</span> error<span class="token operator">=</span><span class="token string">&quot;用户拒绝&quot;</span><span class="token punctuation">)</span>
            
            <span class="token comment"># 3. 执行所有操作</span>
            results <span class="token operator">=</span> <span class="token punctuation">[</span><span class="token punctuation">]</span>
            <span class="token keyword">for</span> params <span class="token keyword">in</span> batch_params<span class="token punctuation">:</span>
                result <span class="token operator">=</span> <span class="token keyword">await</span> tool<span class="token punctuation">.</span>execute<span class="token punctuation">(</span>params<span class="token punctuation">)</span>
                results<span class="token punctuation">.</span>append<span class="token punctuation">(</span>result<span class="token punctuation">)</span>
            
            <span class="token keyword">return</span> ToolResult<span class="token punctuation">(</span>success<span class="token operator">=</span><span class="token boolean">True</span><span class="token punctuation">,</span> results<span class="token operator">=</span>results<span class="token punctuation">)</span>
        
        <span class="token comment"># 单个操作，正常授权</span>
        <span class="token keyword">return</span> <span class="token keyword">await</span> self<span class="token punctuation">.</span>handle_single_operation<span class="token punctuation">(</span>tool<span class="token punctuation">,</span> batch_params<span class="token punctuation">[</span><span class="token number">0</span><span class="token punctuation">]</span><span class="token punctuation">)</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p><strong>批量授权策略</strong>：</p><table><thead><tr><th>批量大小</th><th>授权方式</th></tr></thead><tbody><tr><td>1-3 个</td><td>逐个确认</td></tr><tr><td>4-10 个</td><td>批量确认（显示示例）</td></tr><tr><td>10+ 个</td><td>需要高级确认</td></tr></tbody></table><p><strong>批量授权示例：</strong></p><p>通过显示批量授权摘要，让用户一次性确认，如</p><div class="language-text line-numbers-mode" data-ext="text"><pre class="language-text"><code>你将执行：
- 转账 A 100 元
- 转账 B 200 元
总金额 300 元
是否确认？
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h3 id="_5-4-授权有效期设计" tabindex="-1"><a class="header-anchor" href="#_5-4-授权有效期设计" aria-hidden="true">#</a> 5.4 授权有效期设计</h3><p><strong>核心问题</strong>：用户授权后，有效期内可以重复执行吗？</p><div class="language-python line-numbers-mode" data-ext="py"><pre class="language-python"><code><span class="token keyword">class</span> <span class="token class-name">AuthExpiryManager</span><span class="token punctuation">:</span>
    <span class="token keyword">def</span> <span class="token function">__init__</span><span class="token punctuation">(</span>self<span class="token punctuation">)</span><span class="token punctuation">:</span>
        self_auth_tokens <span class="token operator">=</span> <span class="token punctuation">{</span><span class="token punctuation">}</span>
    
    <span class="token keyword">async</span> <span class="token keyword">def</span> <span class="token function">create_auth_token</span><span class="token punctuation">(</span>
        self<span class="token punctuation">,</span> 
        tool_name<span class="token punctuation">:</span> <span class="token builtin">str</span><span class="token punctuation">,</span> 
        params<span class="token punctuation">:</span> <span class="token builtin">dict</span><span class="token punctuation">,</span> 
        duration_seconds<span class="token punctuation">:</span> <span class="token builtin">int</span> <span class="token operator">=</span> <span class="token number">300</span>
    <span class="token punctuation">)</span> <span class="token operator">-</span><span class="token operator">&gt;</span> <span class="token builtin">str</span><span class="token punctuation">:</span>
        token <span class="token operator">=</span> generate_token<span class="token punctuation">(</span><span class="token punctuation">)</span>
        
        self_auth_tokens<span class="token punctuation">[</span>token<span class="token punctuation">]</span> <span class="token operator">=</span> <span class="token punctuation">{</span>
            <span class="token string">&quot;tool_name&quot;</span><span class="token punctuation">:</span> tool_name<span class="token punctuation">,</span>
            <span class="token string">&quot;params_hash&quot;</span><span class="token punctuation">:</span> hash_params<span class="token punctuation">(</span>params<span class="token punctuation">)</span><span class="token punctuation">,</span>
            <span class="token string">&quot;created_at&quot;</span><span class="token punctuation">:</span> datetime<span class="token punctuation">.</span>now<span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">,</span>
            <span class="token string">&quot;duration&quot;</span><span class="token punctuation">:</span> duration_seconds<span class="token punctuation">,</span>
            <span class="token string">&quot;max_uses&quot;</span><span class="token punctuation">:</span> <span class="token number">1</span><span class="token punctuation">,</span>  <span class="token comment"># 默认一次</span>
            <span class="token string">&quot;used_count&quot;</span><span class="token punctuation">:</span> <span class="token number">0</span><span class="token punctuation">,</span>
        <span class="token punctuation">}</span>
        
        <span class="token keyword">return</span> token
    
    <span class="token keyword">async</span> <span class="token keyword">def</span> <span class="token function">use_auth_token</span><span class="token punctuation">(</span>self<span class="token punctuation">,</span> token<span class="token punctuation">:</span> <span class="token builtin">str</span><span class="token punctuation">,</span> current_params<span class="token punctuation">:</span> <span class="token builtin">dict</span><span class="token punctuation">)</span> <span class="token operator">-</span><span class="token operator">&gt;</span> <span class="token builtin">bool</span><span class="token punctuation">:</span>
        auth <span class="token operator">=</span> self_auth_tokens<span class="token punctuation">.</span>get<span class="token punctuation">(</span>token<span class="token punctuation">)</span>
        
        <span class="token keyword">if</span> <span class="token keyword">not</span> auth<span class="token punctuation">:</span>
            <span class="token keyword">return</span> <span class="token boolean">False</span>
        
        <span class="token comment"># 检查是否过期</span>
        <span class="token keyword">if</span> auth<span class="token punctuation">[</span><span class="token string">&quot;created_at&quot;</span><span class="token punctuation">]</span> <span class="token operator">+</span> auth<span class="token punctuation">[</span><span class="token string">&quot;duration&quot;</span><span class="token punctuation">]</span> <span class="token operator">&lt;</span> datetime<span class="token punctuation">.</span>now<span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">:</span>
            <span class="token keyword">return</span> <span class="token boolean">False</span>
        
        <span class="token comment"># 检查使用次数</span>
        <span class="token keyword">if</span> auth<span class="token punctuation">[</span><span class="token string">&quot;used_count&quot;</span><span class="token punctuation">]</span> <span class="token operator">&gt;=</span> auth<span class="token punctuation">[</span><span class="token string">&quot;max_uses&quot;</span><span class="token punctuation">]</span><span class="token punctuation">:</span>
            <span class="token keyword">return</span> <span class="token boolean">False</span>
        
        <span class="token comment"># 检查参数是否一致</span>
        <span class="token keyword">if</span> auth<span class="token punctuation">[</span><span class="token string">&quot;params_hash&quot;</span><span class="token punctuation">]</span> <span class="token operator">!=</span> hash_params<span class="token punctuation">(</span>current_params<span class="token punctuation">)</span><span class="token punctuation">:</span>
            <span class="token keyword">return</span> <span class="token boolean">False</span>
        
        auth<span class="token punctuation">[</span><span class="token string">&quot;used_count&quot;</span><span class="token punctuation">]</span> <span class="token operator">+=</span> <span class="token number">1</span>
        <span class="token keyword">return</span> <span class="token boolean">True</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p><strong>有效期设计原则</strong>：</p><table><thead><tr><th>操作类型</th><th>推荐有效期</th><th>推荐使用次数</th></tr></thead><tbody><tr><td>转账</td><td>5分钟</td><td>1次</td></tr><tr><td>查看数据</td><td>30分钟</td><td>无限</td></tr><tr><td>发送消息</td><td>10分钟</td><td>1次</td></tr><tr><td>订票</td><td>1小时</td><td>批量次数</td></tr></tbody></table><h3 id="_5-5-敏感工具定义框架" tabindex="-1"><a class="header-anchor" href="#_5-5-敏感工具定义框架" aria-hidden="true">#</a> 5.5 敏感工具定义框架</h3><p><strong>核心问题</strong>：怎么判断一个工具是否&quot;敏感&quot;？</p><p>一个最简单的方案是根据业务归属来确定工具的安全等级，如下</p><figure><img src="https://imgbed.ppai.top/file/1777274066557_m4-08.jpeg" alt="m4-08.jpeg" tabindex="0" loading="lazy"><figcaption>m4-08.jpeg</figcaption></figure><div class="language-python line-numbers-mode" data-ext="py"><pre class="language-python"><code><span class="token keyword">class</span> <span class="token class-name">ToolSensitivityAnalyzer</span><span class="token punctuation">:</span>
    <span class="token keyword">def</span> <span class="token function">__init__</span><span class="token punctuation">(</span>self<span class="token punctuation">)</span><span class="token punctuation">:</span>
        self<span class="token punctuation">.</span>sensitivity_rules <span class="token operator">=</span> <span class="token punctuation">[</span>
            <span class="token comment"># 资金相关</span>
            <span class="token punctuation">(</span><span class="token string">r&quot;transfer|refund|purchase&quot;</span><span class="token punctuation">,</span> Sensitivity<span class="token punctuation">.</span>HIGH<span class="token punctuation">,</span> <span class="token string">&quot;涉及资金&quot;</span><span class="token punctuation">)</span><span class="token punctuation">,</span>
            <span class="token punctuation">(</span><span class="token string">r&quot;payment|recharge&quot;</span><span class="token punctuation">,</span> Sensitivity<span class="token punctuation">.</span>HIGH<span class="token punctuation">,</span> <span class="token string">&quot;涉及充值&quot;</span><span class="token punctuation">)</span><span class="token punctuation">,</span>
            
            <span class="token comment"># 数据相关</span>
            <span class="token punctuation">(</span><span class="token string">r&quot;delete|remove|drop&quot;</span><span class="token punctuation">,</span> Sensitivity<span class="token punctuation">.</span>MEDIUM<span class="token punctuation">,</span> <span class="token string">&quot;涉及删除&quot;</span><span class="token punctuation">)</span><span class="token punctuation">,</span>
            <span class="token punctuation">(</span><span class="token string">r&quot;export|dump&quot;</span><span class="token punctuation">,</span> Sensitivity<span class="token punctuation">.</span>MEDIUM<span class="token punctuation">,</span> <span class="token string">&quot;涉及导出&quot;</span><span class="token punctuation">)</span><span class="token punctuation">,</span>
            <span class="token punctuation">(</span><span class="token string">r&quot;send|publish&quot;</span><span class="token punctuation">,</span> Sensitivity<span class="token punctuation">.</span>MEDIUM<span class="token punctuation">,</span> <span class="token string">&quot;涉及发布&quot;</span><span class="token punctuation">)</span><span class="token punctuation">,</span>
            
            <span class="token comment"># 权限相关</span>
            <span class="token punctuation">(</span><span class="token string">r&quot;grant|revoke|admin&quot;</span><span class="token punctuation">,</span> Sensitivity<span class="token punctuation">.</span>CRITICAL<span class="token punctuation">,</span> <span class="token string">&quot;涉及权限&quot;</span><span class="token punctuation">)</span><span class="token punctuation">,</span>
            <span class="token punctuation">(</span><span class="token string">r&quot;password|credential&quot;</span><span class="token punctuation">,</span> Sensitivity<span class="token punctuation">.</span>CRITICAL<span class="token punctuation">,</span> <span class="token string">&quot;涉及凭证&quot;</span><span class="token punctuation">)</span><span class="token punctuation">,</span>
            
            <span class="token comment"># 安全相关</span>
            <span class="token punctuation">(</span><span class="token string">r&quot;oauth|login|auth&quot;</span><span class="token punctuation">,</span> Sensitivity<span class="token punctuation">.</span>CRITICAL<span class="token punctuation">,</span> <span class="token string">&quot;涉及认证&quot;</span><span class="token punctuation">)</span><span class="token punctuation">,</span>
        <span class="token punctuation">]</span>
    
    <span class="token keyword">def</span> <span class="token function">analyze</span><span class="token punctuation">(</span>self<span class="token punctuation">,</span> tool_name<span class="token punctuation">:</span> <span class="token builtin">str</span><span class="token punctuation">,</span> tool_docs<span class="token punctuation">:</span> <span class="token builtin">str</span><span class="token punctuation">)</span> <span class="token operator">-</span><span class="token operator">&gt;</span> SensitivityResult<span class="token punctuation">:</span>
        combined <span class="token operator">=</span> <span class="token string-interpolation"><span class="token string">f&quot;</span><span class="token interpolation"><span class="token punctuation">{</span>tool_name<span class="token punctuation">}</span></span><span class="token string"> </span><span class="token interpolation"><span class="token punctuation">{</span>tool_docs<span class="token punctuation">}</span></span><span class="token string">&quot;</span></span>
        
        <span class="token keyword">for</span> pattern<span class="token punctuation">,</span> sensitivity<span class="token punctuation">,</span> reason <span class="token keyword">in</span> self<span class="token punctuation">.</span>sensitivity_rules<span class="token punctuation">:</span>
            <span class="token keyword">if</span> re<span class="token punctuation">.</span>search<span class="token punctuation">(</span>pattern<span class="token punctuation">,</span> combined<span class="token punctuation">,</span> re<span class="token punctuation">.</span>IGNORECASE<span class="token punctuation">)</span><span class="token punctuation">:</span>
                <span class="token keyword">return</span> SensitivityResult<span class="token punctuation">(</span>
                    level<span class="token operator">=</span>sensitivity<span class="token punctuation">,</span>
                    reason<span class="token operator">=</span>reason<span class="token punctuation">,</span>
                    requires_auth<span class="token operator">=</span>sensitivity <span class="token operator">&gt;=</span> Sensitivity<span class="token punctuation">.</span>MEDIUM<span class="token punctuation">,</span>
                <span class="token punctuation">)</span>
        
        <span class="token keyword">return</span> SensitivityResult<span class="token punctuation">(</span>level<span class="token operator">=</span>Sensitivity<span class="token punctuation">.</span>LOW<span class="token punctuation">,</span> reason<span class="token operator">=</span><span class="token string">&quot;默认&quot;</span><span class="token punctuation">)</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h2 id="_6-面试加分项" tabindex="-1"><a class="header-anchor" href="#_6-面试加分项" aria-hidden="true">#</a> 6. 面试加分项</h2><figure><img src="https://imgbed.ppai.top/file/1777274077139_m4-09.jpeg" alt="m4-09.jpeg" tabindex="0" loading="lazy"><figcaption>m4-09.jpeg</figcaption></figure><h3 id="_6-1-展示安全意识" tabindex="-1"><a class="header-anchor" href="#_6-1-展示安全意识" aria-hidden="true">#</a> 6.1 展示安全意识</h3><p><strong>差异化表达</strong>：</p><blockquote><p>&quot;敏感工具授权的本质矛盾是：Agent 的优势是自动化，但自动化意味着减少用户干预；而安全意味着增加用户确认。这两者天然矛盾。我的设计思路是分级——低敏感操作放行，高敏感操作拦截，在保证安全的前提下最大化自动化。&quot;</p></blockquote><h3 id="_6-2-展示工程化思维" tabindex="-1"><a class="header-anchor" href="#_6-2-展示工程化思维" aria-hidden="true">#</a> 6.2 展示工程化思维</h3><p><strong>全面性回答</strong>：</p><blockquote><p>&quot;我的设计包含五个核心组件：敏感级别定义器（定义哪些工具需要授权）、授权策略选择器（根据级别选择授权方式）、参数锁定器（锁定授权时的参数）、上下文同步器（同步授权时的状态）、有效期管理器（管理授权有效期）。每个组件独立可配置，便于扩展。&quot;</p></blockquote><h3 id="_6-3-展示实际项目经验" tabindex="-1"><a class="header-anchor" href="#_6-3-展示实际项目经验" aria-hidden="true">#</a> 6.3 展示实际项目经验</h3><p><strong>数据驱动</strong>：</p><blockquote><p>&quot;我们上线后发现，80% 的操作是查询类（无需授权），15% 是普通操作（简单确认），只有 5% 是高敏感操作（显式确认）。通过分级授权，既保证了安全，又避免了过度干扰用户体验。&quot;</p></blockquote><h3 id="_6-4-展示权衡思维" tabindex="-1"><a class="header-anchor" href="#_6-4-展示权衡思维" aria-hidden="true">#</a> 6.4 展示权衡思维</h3><p><strong>场景化回答</strong>：</p><blockquote><p>&quot;自动化和安全性是 Trade-off 关系。如果安全要求高，就增加授权环节，用户体验下降；如果追求用户体验，就减少授权环节，安全风险增加。我的方案是通过分级授权让用户选择：低敏感操作快速执行，高敏感操作强制确认。&quot;</p></blockquote><h2 id="_7-常见面试追问" tabindex="-1"><a class="header-anchor" href="#_7-常见面试追问" aria-hidden="true">#</a> 7. 常见面试追问</h2><h3 id="q1-授权通过后-参数被人篡改了怎么办" tabindex="-1"><a class="header-anchor" href="#q1-授权通过后-参数被人篡改了怎么办" aria-hidden="true">#</a> Q1：授权通过后，参数被人篡改了怎么办？</h3><p><strong>参考答案</strong>：应该在授权时锁定参数，执行时校验参数哈希。如果参数变了，不仅要拒绝执行，还要记录安全事件。</p><h3 id="q2-如果用户连续点击授权会很烦怎么办" tabindex="-1"><a class="header-anchor" href="#q2-如果用户连续点击授权会很烦怎么办" aria-hidden="true">#</a> Q2：如果用户连续点击授权会很烦怎么办？</h3><p><strong>参考答案</strong>：可以设计&quot;本次授权&quot;和&quot;本次会话授权&quot;两种模式。本次授权只对当前操作有效，本次会话授权在会话期间内对同类操作有效。让用户选择。</p><h3 id="q3-紧急情况下需要跳过授权吗" tabindex="-1"><a class="header-anchor" href="#q3-紧急情况下需要跳过授权吗" aria-hidden="true">#</a> Q3：紧急情况下需要跳过授权吗？</h3><p><strong>参考答案</strong>：不应该跳过，但可以设计&quot;紧急模式&quot;——紧急模式下记录更详细的审计日志，事后可以追溯和审核。</p><h3 id="q4-授权可以代理吗-比如让管理员统一授权" tabindex="-1"><a class="header-anchor" href="#q4-授权可以代理吗-比如让管理员统一授权" aria-hidden="true">#</a> Q4：授权可以代理吗？比如让管理员统一授权？</h3><p><strong>参考答案</strong>：可以设计授权代理机制，但需要限制代理范围、代理时间、记录代理操作。敏感操作不建议代理。</p><h3 id="q5-在上面的设计中-还有什么需要补充的吗" tabindex="-1"><a class="header-anchor" href="#q5-在上面的设计中-还有什么需要补充的吗" aria-hidden="true">#</a> Q5: 在上面的设计中，还有什么需要补充的吗？</h3><p><strong>参考答案</strong>：敏感工具授权的本质是一个多层的安全机制的设计问题，不能只靠Agent层来解决，在上面的设计中，分别介绍了 策略层（预授权），交互层（执行前授权），执行层（Tool执行校验），但是还有一些安全审计、监控相关的实现同样也是生产环境中不可缺少的部分，如（日志记录+防重放幂等设计+最小权限原则+上下文隔离限制+动态风险评估）等，也是我们在实现的过程中需要考虑的因素</p><h2 id="_8-总结" tabindex="-1"><a class="header-anchor" href="#_8-总结" aria-hidden="true">#</a> 8. 总结</h2><table><thead><tr><th>考察维度</th><th>核心要点</th></tr></thead><tbody><tr><td>问题识别</td><td>自动化 vs 安全性的矛盾</td></tr><tr><td>方案设计</td><td>分级授权体系</td></tr><tr><td>工程实现</td><td>参数锁定 + 上下文同步 + 有效期管理</td></tr><tr><td>效果评估</td><td>安全与体验的平衡</td></tr><tr><td>面试话术</td><td>场景化 + 分级化 + 工程化</td></tr></tbody></table><p><strong>一句话总结</strong>：</p><p>面试时，要展示你对安全工程的理解，以及如何在保证安全的前提下最大化用户体验。</p><blockquote><p>&quot;敏感工具授权的本质不是拦截用户，而是信任分级——低敏感操作信任用户，高敏感操作验证用户。我的设计思路是：把安全留给高风险场景，把便捷留给日常操作。&quot;</p></blockquote><h2 id="参考资料" tabindex="-1"><a class="header-anchor" href="#参考资料" aria-hidden="true">#</a> 参考资料</h2>`,114),k=n("thead",null,[n("tr",null,[n("th",null,"参考资料"),n("th",null,"访问地址")])],-1),v=n("td",null,"Human-in-the-Loop 设计模式",-1),m={href:"https://arxiv.org/abs/2310.02989",target:"_blank",rel:"noopener noreferrer"},b=n("td",null,"OAuth 2.0 授权框架",-1),h={href:"https://oauth.net/2/",target:"_blank",rel:"noopener noreferrer"},g=n("td",null,"AWS IAM 权限管理最佳实践",-1),_={href:"https://aws.amazon.com/iam/",target:"_blank",rel:"noopener noreferrer"},y=n("blockquote",null,[n("p",null,[n("strong",null,"作者"),s("：一灰"),n("br"),n("strong",null,"日期"),s("：2026-04-27"),n("br"),n("strong",null,"标签"),s("： #Agent #面试 #敏感工具授权 #安全")])],-1);function q(f,w){const o=e("Mermaid"),t=e("ExternalLinkIcon");return i(),l("div",null,[r,a(o,{id:"mermaid-173",code:""}),d,n("table",null,[k,n("tbody",null,[n("tr",null,[v,n("td",null,[n("a",m,[s("https://arxiv.org/abs/2310.02989"),a(t)])])]),n("tr",null,[b,n("td",null,[n("a",h,[s("https://oauth.net/2/"),a(t)])])]),n("tr",null,[g,n("td",null,[n("a",_,[s("https://aws.amazon.com/iam/"),a(t)])])])])]),y])}const A=c(u,[["render",q],["__file","04.Agent敏感工具授权：面试高频问题详解.html.vue"]]);export{A as default};
